import XCTest
@testable import RdevCore

/// The v3 carrier, against the SAME cross-implementation vectors the TypeScript suite asserts
/// (`protocol/fixtures/pairing-v3.json`, generated by a third implementation). A parser that agrees
/// with itself and with nothing else is the failure this repo has paid for before.
///
/// The v2 encoder is GONE — the host prints a seed now — so what used to be an encode/decode round
/// trip is a derivation against fixed answers, which is the stronger of the two.
final class PairingTests: XCTestCase {

    private struct Case: Decodable {
        let name: String, seed: String, encoded: String, code: String, token: String, psk: String
    }
    private struct Fixture: Decodable { let cases: [Case] }

    private static let fx: Fixture = {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("protocol/fixtures/pairing-v3.json")
        return try! JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
    }()

    private func hex(_ s: String) -> [UInt8] {
        stride(from: 0, to: s.count, by: 2).map {
            let i = s.index(s.startIndex, offsetBy: $0)
            return UInt8(s[i ... s.index(after: i)], radix: 16)!
        }
    }

    func testEveryCrossImplementationVector() throws {
        for c in Self.fx.cases {
            let p = try XCTUnwrap(parsePairing(c.encoded), c.name)
            XCTAssertEqual(p.code, c.code, c.name)
            XCTAssertEqual(p.token, c.token, c.name)
            XCTAssertEqual(p.psk, hex(c.psk), c.name)
        }
    }

    /// The session Durable Object compares the token as an exact string against what the derivation
    /// produced, so an uppercase one is refused as `bad-token` — which presents as a wrong pairing
    /// code rather than as a formatting bug.
    func testTheTokenIsCanonicalLowercase() throws {
        let p = try XCTUnwrap(parsePairing(Self.fx.cases[0].encoded))
        XCTAssertEqual(p.token, p.token.lowercased())
    }

    // MARK: - links

    /// **THE SEED TRAVELS IN THE FRAGMENT.** A query string is sent to the Control Plane on the
    /// first navigation and §9.1 forbids the seed reaching it.
    func testASeedIsReadFromALinksFragment() throws {
        let c = Self.fx.cases[0]
        let p = try XCTUnwrap(parsePairing("https://host.example/#pair=\(c.encoded)"))
        XCTAssertEqual(p.code, c.code)
        XCTAssertNotNil(p.psk)
    }

    func testTheFragmentsSeedBeatsAWeakerCodeAndTokenInTheQuery() throws {
        let c = Self.fx.cases[0]
        let p = try XCTUnwrap(parsePairing(
            "https://h/?code=WRONGcod&token=00000000-0000-4000-8000-000000000000#pair=\(c.encoded)"))
        XCTAssertEqual(p.code, c.code)
        XCTAssertNotNil(p.psk)
    }

    /// Reading a seed from the query would turn a correct link into a leak the moment somebody
    /// rewrote it by hand.
    func testASeedOfferedInTheQueryIsRefused() {
        XCTAssertNil(parsePairing("https://h/?pair=\(Self.fx.cases[0].encoded)"))
    }

    /// A `?code=&token=` link admits a client to the room and gives it NOTHING to handshake `pair`
    /// with. The absent psk is asserted rather than assumed.
    func testAPlainLinkCarriesNoPSK() throws {
        let p = try XCTUnwrap(parsePairing(
            "https://host.example/?code=rm5skaUZ&token=d5a9507e-22e8-49e7-8a9d-045c82960c23"))
        XCTAssertEqual(p.code, "rm5skaUZ")
        XCTAssertEqual(p.token, "d5a9507e-22e8-49e7-8a9d-045c82960c23")
        XCTAssertNil(p.psk)
    }

    func testABareQueryString() throws {
        let p = try XCTUnwrap(parsePairing("?code=abc&token=xyz"))
        XCTAssertEqual(p.code, "abc")
    }

    func testRefusals() {
        XCTAssertNil(parsePairing(""))
        XCTAssertNil(parsePairing("   "))
        XCTAssertNil(parsePairing("!!! not base64 !!!"))
        XCTAssertNil(parsePairing("https://h/?code=rm5skaUZ"))
        // 30 characters, token-first — the RETIRED v2 carrier. §9.1 requires the two cannot be
        // confused in either direction, and the carrier's exact 22-character shape guarantees it
        // now that the `ss3.` prefix is gone.
        XCTAssertNil(parsePairing("1alQfiLoSeeKnQRcgpYMI65ubJGlGQ"))
    }

    func testWhitespaceIsTrimmed() throws {
        let c = Self.fx.cases[0]
        let p = try XCTUnwrap(parsePairing("  \(c.encoded)  "))
        XCTAssertEqual(p.code, c.code)
    }
}
